const fs=require('fs');
const path=require('path');

const root=path.resolve(__dirname,'..');
const dist=path.join(root,'dist');

const bundles=[
  ['core.js',['shared-utils.js','app-1.js','app-2.js','app-3.js','app-4.js']],
  ['bookings.js',['app-5.js','app-6.js','app-7.js','app-8.js','app-9.js','app-10.js','app-11.js']],
  ['staffing.js',['app-12.js','app-13.js','app-14.js','app-15.js']],
  ['access.js',['app-16.js','app-17.js','app-18.js','app-19.js']],
  ['calendar.js',['app-20.js','app-21.js','app-22.js','app-23.js','app-24.js','app-25.js','app-26.js','app-27.js','app-28.js','app-29.js']],
  ['billing.js',['app-30.js','app-31.js','app-32.js','app-33.js','app-34.js','app-35.js','app-36.js','app-37.js','app-38.js','app-40.js']],
  ['viewer-access.js',['app-44.js','app-45.js','app-46.js','app-47.js','app-48.js','app-49.js']]
];

const allSources=bundles.flatMap(([,files])=>files);
const dynamicLoaderMarker="(function(){const css=document.createElement('link');css.rel='stylesheet';css.href='admin-access.css';";

function readSource(file){
  const full=path.join(root,file);
  if(!fs.existsSync(full))throw new Error(`Missing runtime source: ${file}`);
  let source=fs.readFileSync(full,'utf8');
  if(file==='app-15.js'){
    const marker=source.indexOf(dynamicLoaderMarker);
    if(marker<0)throw new Error('app-15.js dynamic loader marker changed; refusing to build until the loader is reviewed.');
    source=source.slice(0,marker).trimEnd();
  }
  return `/* source: ${file} */\n${source}\n`;
}

function copyFile(name){fs.copyFileSync(path.join(root,name),path.join(dist,name));}

fs.rmSync(dist,{recursive:true,force:true});
fs.mkdirSync(dist,{recursive:true});

for(const [name,files] of bundles){
  const content=`/* Generated by scripts/build-bundles.js. Do not edit dist directly. */\n${files.map(readSource).join('\n;\n')}`;
  fs.writeFileSync(path.join(dist,name),content);
}

for(const entry of fs.readdirSync(root,{withFileTypes:true})){
  if(!entry.isFile())continue;
  if(/\.(css|png|jpe?g|svg|ico|webp|woff2?)$/i.test(entry.name))copyFile(entry.name);
}

let html=fs.readFileSync(path.join(root,'index.html'),'utf8');
const oldScripts=/<script src="shared-utils\.js"><\/script><script src="app-1\.js"><\/script><script src="app-2\.js"><\/script><script src="app-3\.js"><\/script><script src="app-4\.js"><\/script><script src="app-5\.js"><\/script><script src="app-6\.js"><\/script><script src="app-7\.js"><\/script><script src="app-8\.js"><\/script><script src="app-9\.js"><\/script><script src="app-10\.js"><\/script><script src="app-11\.js"><\/script><script src="app-12\.js"><\/script><script src="app-13\.js"><\/script><script src="app-14\.js"><\/script><script src="app-15\.js"><\/script>/;
if(!oldScripts.test(html))throw new Error('index.html runtime script block changed; refusing to build until the entry point is reviewed.');
const bundleTags=bundles.map(([name])=>`<script src="${name}"></script>`).join('');
html=html.replace(oldScripts,bundleTags);
if(!html.includes('href="admin-access.css"'))html=html.replace('</head>','<link rel="stylesheet" href="admin-access.css">\n</head>');
fs.writeFileSync(path.join(dist,'index.html'),html);

const manifest={
  generatedAt:new Date().toISOString(),
  bundleCount:bundles.length,
  sourceCount:allSources.length,
  bundles:Object.fromEntries(bundles)
};
fs.writeFileSync(path.join(dist,'runtime-manifest.json'),JSON.stringify(manifest,null,2)+'\n');
console.log(`Built ${bundles.length} ordered bundles from ${allSources.length} runtime sources.`);
